{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "FK788, which shares the carboxymethoxy-aromatic and hydroxylated fused-ring features of the query, had an absolute oral bioavailability of 55% in healthy volunteers, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Etodolac, a lipophilic carboxylic acid, had an absolute oral bioavailability of 80% in humans, supporting high oral bioavailability for an acidic molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Propranolol, despite extensive first-pass metabolism, showed mean absolute bioavailability of 30–35% in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "KNI-272 administered post-prandially had an absolute bioavailability of 36.4%, providing fed-state evidence that F remains above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Bevantolol had a mean absolute bioavailability of 57% (range 26–98%) in subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Diacetolol had a mean absolute bioavailability of 42.6% after oral dosing, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "One propranolol record calculated F = 0.17 in normal subjects, below the 20% threshold; however, this conflicts with multiple other propranolol measurements and is outweighed by structurally closer high-F analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The preponderance of highly transferable experimental evidence, including structurally close FK788 (55%) and etodolac (80%), plus multiple beta-blockers and other drugs with F ≥ 30%, supports absolute oral bioavailability ≥ 20%. The single sub-threshold propranolol record (17%) is an outlier and does not overturn the consistent high-F pattern; fed-state KNI-272 data also remain above threshold.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule itself.",
    "Fed-state absolute F data are limited to KNI-272; most evidence is fasting or unspecified.",
    "The query's prostaglandin-like scaffold is not directly represented among the evidence molecules, though FK788 and etodolac share key acidic/aromatic features."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

